// n8n Code node "Check the Report" in "SEO Engine: Weekly Report" (mode: Run Once for All Items).
// The Monday report from GitHub (.github/workflows/seo-weekly.yml, step "Send the report to the bot", n8n/seo-engine/notify_n8n.py).
// CLAUDE.md rule 8: signature first, then the JSON Schema; anything else goes to the dead-letter queue and nothing else runs.
//  1. The signature: the webhook node already refused any request without a valid JWT signed with the n8n credential
//     "DTJ SEO Report Key" (HS256, the same secret as GitHub's N8N_SEO_REPORT_KEY). Here: its claims (issuer, audience, 15 minutes at
//     most) and the SHA-256 of the body's "content" text, which the signature covers, so not one character can change on the way.
//  2. The schema: schemas/seo-weekly-report.schema.json, written out below (n8n's Code step has no schema library); the tests run
//     the same samples through both and expect the same verdict.
// Output: one item, { ok: true, report } or { ok: false, reason, raw } ("Plan the Report" sends the second to the dead-letter table).
const item = $input.first().json || {};
const body = item.body && typeof item.body === 'object' ? item.body : {};
const rawText = (() => { try { return JSON.stringify(item.body === undefined ? null : item.body); } catch (e) { return String(item.body); } })();
const bad = (reason) => [{ json: { ok: false, reason, raw: String(rawText).slice(0, 20000) } }];
const REPO = 'harsh-shopify-dev/dtj-agency-automation';

// ---- SHA-256 of a text's UTF-8 bytes (no crypto module in n8n's Code step) ----
function utf8(s) {
  const out = [];
  for (let i = 0; i < s.length; i++) {
    let c = s.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
      const d = s.charCodeAt(i + 1);
      if (d >= 0xdc00 && d <= 0xdfff) { c = 0x10000 + ((c - 0xd800) << 10) + (d - 0xdc00); i++; }
    }
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return out;
}
function sha256hex(text) {
  const K = [0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5, 0xd807aa98, 0x12835b01,
    0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174, 0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f,
    0x4a7484aa, 0x5cb0a9dc, 0x76f988da, 0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85, 0xa2bfe8a1, 0xa81a664b, 0xc24b8b70,
    0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070, 0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a,
    0x5b9cca4f, 0x682e6ff3, 0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2];
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const bytes = utf8(text);
  const bitLen = bytes.length * 8;
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) bytes.push(0);
  const hi = Math.floor(bitLen / 0x100000000), lo = bitLen >>> 0;
  bytes.push((hi >>> 24) & 255, (hi >>> 16) & 255, (hi >>> 8) & 255, hi & 255, (lo >>> 24) & 255, (lo >>> 16) & 255, (lo >>> 8) & 255, lo & 255);
  const W = new Array(64);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let off = 0; off < bytes.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      W[t] = ((bytes[off + 4 * t] << 24) | (bytes[off + 4 * t + 1] << 16) | (bytes[off + 4 * t + 2] << 8) | bytes[off + 4 * t + 3]) >>> 0;
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(W[t - 15], 7) ^ rotr(W[t - 15], 18) ^ (W[t - 15] >>> 3);
      const s1 = rotr(W[t - 2], 17) ^ rotr(W[t - 2], 19) ^ (W[t - 2] >>> 10);
      W[t] = (W[t - 16] + s0 + W[t - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const t1 = (h + S1 + ((e & f) ^ (~e & g)) + K[t] + W[t]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const t2 = (S0 + ((a & b) ^ (a & c) ^ (b & c))) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
    H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
  }
  return H.map((x) => x.toString(16).padStart(8, '0')).join('');
}

// ---- the signature's claims: from the webhook node (jwtPayload), else read from the header it has already verified ----
function claimsFromHeader() {
  const auth = String((item.headers || {}).authorization || '');
  const m = auth.match(/^Bearer\s+[A-Za-z0-9_-]+\.([A-Za-z0-9_-]+)\.[A-Za-z0-9_-]+$/);
  if (!m) return null;
  try {
    const b64 = m[1].replace(/-/g, '+').replace(/_/g, '/');
    return JSON.parse(Buffer.from(b64, 'base64').toString('utf8'));
  } catch (e) { return null; }
}
const claims = (item.jwtPayload && typeof item.jwtPayload === 'object') ? item.jwtPayload : claimsFromHeader();
if (!claims) return bad('no signed claims: the request did not carry the JWT the webhook checks');
const now = Math.floor(Date.now() / 1000);
if (claims.iss !== 'dtj-seo-weekly' || claims.aud !== 'dtj-n8n') return bad('the signature was not made for this report (issuer or audience)');
if (typeof claims.exp !== 'number' || typeof claims.iat !== 'number') return bad('the signature has no time on it');
if (claims.exp < now) return bad('the signature has expired (older than its 15 minutes)');
if (claims.iat > now + 120 || claims.exp - claims.iat > 900) return bad('the signature\'s times are not valid');
if (typeof body.content !== 'string' || !body.content) return bad('the body has no "content" text');
if (body.content.length > 200000) return bad('the report is too large (more than 200,000 characters)');
if (Object.keys(body).some((k) => k !== 'content')) return bad('the body has fields other than "content"');
if (sha256hex(body.content) !== String(claims.sha256 || '').toLowerCase()) return bad('the content does not match its signature (SHA-256)');

let r;
try { r = JSON.parse(body.content); } catch (e) { return bad('the content is not valid JSON'); }

// ---- schemas/seo-weekly-report.schema.json ----
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const isInt = (v) => Number.isInteger(v) && v >= 0;
const str = (v, max, re) => typeof v === 'string' && v.length <= max && (!re || re.test(v));
function only(o, allowed) { return Object.keys(o).every((k) => allowed.includes(k)); }
function check(r) {
  if (!isObj(r)) return 'the report is not an object';
  const top = ['schema', 'repo', 'run_id', 'run_url', 'ref', 'made_at', 'site', 'mode', 'scan', 'batch', 'report_md'];
  for (const k of top.filter((k) => k !== 'mode')) if (!(k in r)) return 'missing ' + k;
  if (!only(r, top)) return 'unknown field at the top: ' + Object.keys(r).filter((k) => !top.includes(k)).join(', ');
  if (r.schema !== 'dtj-seo-weekly/1') return 'schema is not dtj-seo-weekly/1';
  if (!str(r.repo, 200, /^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/)) return 'repo is not owner/name';
  if (!str(r.run_id, 20, /^[0-9]{1,20}$/)) return 'run_id is not a run number';
  if (!str(r.run_url, 300, /^https:\/\/github\.com\/[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+\/actions\/runs\/[0-9]{1,20}$/)) return 'run_url is not a GitHub run link';
  if (!str(r.ref, 200) || !r.ref) return 'ref is empty';
  if (!str(r.made_at, 40, /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9:.]+(Z|[+-][0-9]{2}:[0-9]{2})$/)) return 'made_at is not a date and time';
  if (!str(r.site, 200, /^https:\/\/[^\s]+$/)) return 'site is not an https address';
  if ('mode' in r && !['shadow', 'approve', 'auto'].includes(r.mode)) return 'mode is not shadow, approve or auto';
  const s = r.scan;
  if (!isObj(s)) return 'scan is not an object';
  for (const k of ['pages', 'high', 'medium', 'low', 'complete']) if (!(k in s)) return 'scan: missing ' + k;
  if (!only(s, ['pages', 'high', 'medium', 'low', 'complete', 'warning'])) return 'scan: unknown field';
  if (!['pages', 'high', 'medium', 'low'].every((k) => isInt(s[k]))) return 'scan: counts must be whole numbers';
  if (typeof s.complete !== 'boolean') return 'scan: complete must be true or false';
  if ('warning' in s && !str(s.warning, 2000)) return 'scan: warning too long';
  const b = r.batch;
  if (!isObj(b)) return 'batch is not an object';
  for (const k of ['id', 'counts', 'changes', 'manual', 'notes']) if (!(k in b)) return 'batch: missing ' + k;
  if (!only(b, ['id', 'counts', 'changes', 'manual', 'notes'])) return 'batch: unknown field';
  if (!str(b.id, 40, /^fix-[0-9]{4}-[0-9]{2}-[0-9]{2}$/)) return 'batch: id is not fix-YYYY-MM-DD';
  if (!isObj(b.counts) || !only(b.counts, ['auto', 'blocked', 'manual']) || !['auto', 'blocked', 'manual'].every((k) => isInt(b.counts[k]))) {
    return 'batch: counts must be auto, blocked and manual whole numbers';
  }
  if (!Array.isArray(b.changes) || b.changes.length > 200) return 'batch: changes must be a list of at most 200';
  for (const c of b.changes) {
    if (!isObj(c)) return 'batch: a change is not an object';
    for (const k of ['cid', 'kind', 'url', 'before', 'after', 'how']) if (!(k in c)) return 'batch: a change is missing ' + k;
    if (!only(c, ['cid', 'kind', 'url', 'before', 'after', 'how', 'why'])) return 'batch: a change has an unknown field';
    if (!str(c.cid, 6, /^c[0-9]{3,5}$/)) return 'batch: a change id is not c001 style';
    if (!str(c.kind, 40, /^[a-z_]{1,40}$/)) return 'batch: a change kind is not valid';
    if (!str(c.url, 500) || !c.url) return 'batch: a change has no page';
    if (!(c.before === null || str(c.before, 600))) return 'batch: a change\'s "before" is too long';
    if (!str(c.after, 600)) return 'batch: a change\'s "after" is too long';
    if (!['auto', 'blocked'].includes(c.how)) return 'batch: a change is neither auto nor blocked';
    if ('why' in c && !str(c.why, 600)) return 'batch: a change\'s "why" is too long';
  }
  if (b.changes.filter((c) => c.how === 'auto').length !== b.counts.auto) return 'batch: the auto count does not match the list';
  if (!Array.isArray(b.manual) || b.manual.length > 50 || !b.manual.every((x) => str(x, 600))) return 'batch: manual must be at most 50 short texts';
  if (!Array.isArray(b.notes) || b.notes.length > 50 || !b.notes.every((x) => str(x, 600))) return 'batch: notes must be at most 50 short texts';
  if (!str(r.report_md, 60000) || !r.report_md) return 'report_md is empty or longer than 60,000 characters';
  return '';
}
const problem = check(r);
if (problem) return bad('the report does not match its schema: ' + problem);
if (r.repo !== REPO) return bad('the report is from another repository: ' + r.repo);
if (String(claims.run_id) !== r.run_id || String(claims.batch_id) !== r.batch.id) return bad('the signed run or batch is not the one in the report');
return [{ json: { ok: true, report: r } }];

// n8n Code node "Plan the Report" in "SEO Engine: Weekly Report" (mode: Run Once for All Items).
// After "Check the Report": who gets it, the row for dtj_seo_batches, the action-log row, or the dead letter.
// Who gets it: the active admins in dtj_bot_users (the people who may give a Tier 2 yes: Harsh, or a teammate when he is not
// reachable). A Yes button only when there is something to apply AND the website check read the whole site (report.py says
// "run the check again before saying yes" otherwise).
// The same GitHub run twice (a retried send) is sent once: a run already in dtj_seo_batches gives no output.
// Output: one item, action "save" (row, report, admins, log) or "dead_letter" (dead, admins, log), or nothing.
const checked = $('Check the Report').first().json || {};  // (this node's own input is the batch rows)
const users = $('Load Bot Users').all().map((i) => i.json).filter((u) => u && u.telegram_user_id && u.active !== false);
const batches = $('Load Batches').all().map((i) => i.json).filter((b) => b && b.batch_id);
const admins = [...new Set(users.filter((u) => String(u.role || '').toLowerCase().trim() === 'admin')
  .map((u) => String(u.telegram_user_id).trim()))];
const now = new Date().toISOString();
const log = (fields) => ({ ts: now, run_id: '', client_id: 'dtj', automation: 'seo-engine-n8n', tier: 0, mode: 'shadow', target: '',
  action: '', reason: '', result: 'success', evidence: '', before: '', after: '', approved_by: '', approved_at: '', error: '', ...fields });

if (!checked.ok) {
  return [{ json: {
    action: 'dead_letter', admins,
    dead: { received_at: now, source: 'SEO Engine: Weekly Report', reason: String(checked.reason || 'unknown').slice(0, 500),
      raw: String(checked.raw || '').slice(0, 20000), replayed: '' },
    log: log({ target: 'Monday SEO report', action: 'receive weekly report', reason: 'CLAUDE.md rule 8: signature and schema first',
      result: 'blocked', error: String(checked.reason || '').slice(0, 500) }),
  } }];
}

const r = checked.report;
if (batches.some((b) => String(b.run_id) === r.run_id)) return [];

const c = r.batch.counts;
const canApprove = c.auto > 0 && r.scan.complete === true;
const row = {
  batch_id: r.batch.id, run_id: r.run_id, run_url: r.run_url, report_date: String(r.made_at).slice(0, 10), made_at: r.made_at,
  site: r.site, status: canApprove ? 'waiting' : 'not asked', can_approve: canApprove, auto_changes: c.auto,
  blocked_changes: c.blocked, manual_tasks: c.manual, pages_checked: r.scan.pages, check_complete: r.scan.complete,
  sent_to: admins.length, received_at: now, answered_by: '', approved_by: '', answered_at: '', apply_status: '',
};
return [{ json: {
  action: 'save', row, report: r, admins,
  log: log({ run_id: r.run_id, target: r.site + ' fixes batch ' + r.batch.id, action: 'send weekly report to the bot',
    reason: 'Monday SEO report: one named yes per batch', result: canApprove ? 'recommended' : 'success',
    evidence: JSON.stringify({ run_url: r.run_url, counts: c, pages: r.scan.pages, complete: r.scan.complete, admins: admins.length }) }),
} }];

// n8n Code node "Report Messages" in "SEO Engine: Weekly Report" (mode: Run Once for All Items).
// After "Save the Batch" (the new dtj_seo_batches row, whose id the buttons carry): for each admin, the full report as a file and
// a short message in plain words with the fixes and, when there is something to approve, the Yes / No buttons.
// The buttons say seo:yes:<row id> / seo:no:<row id>; the bot's "Who Is It" hands a tap to this workflow's answer lane.
// Output: items of kind "file" (Send the Report File), "ask" (Ask Yes or No) or "text" (Send).
const APPLY_ON = false;  // must equal APPLY_ON in answer_plan.js (the tests check): false = shadow, a yes is recorded, nothing applied
const plan = $('Plan the Report').first().json;
const saved = $input.first().json || {};
const r = plan.report;
const row = plan.row;
const rowId = Number(saved.id);
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const KIND = { meta_description: 'Google description', seo_title: 'Google title', noindex: 'Hide from Google', alt_text: 'Image alt text',
  site_jsonld: 'Business details for Google and AI' };
if (!Number.isInteger(rowId) || rowId < 1) return [];

const page = (url) => {
  const u = String(url || '');
  const site = String(r.site || '').replace(/\/+$/, '');
  return u.startsWith(site) ? (u.slice(site.length) || '/') : u;
};
const cut = (s, n) => { const t = String(s == null ? '' : s); return t.length > n ? t.slice(0, n - 1) + '…' : t; };
const day = String(r.made_at).slice(0, 10);
const c = r.batch.counts;
const auto = r.batch.changes.filter((x) => x.how === 'auto');
const kind = row.can_approve ? 'ask' : 'text';

function build(show) {
  const L = [];
  L.push('<b>DTJ search report, ' + esc(day) + '</b>');
  L.push('Website check: ' + r.scan.pages + ' pages. ' + r.scan.high + ' to fix now, ' + r.scan.medium + ' soon, ' + r.scan.low + ' later.');
  if (!r.scan.complete) L.push('\n⚠️ <b>This check is incomplete:</b> ' + esc(r.scan.warning || 'part of the site was not read') + '.');
  L.push('');
  L.push('<b>Fixes waiting for one yes</b> (batch ' + esc(r.batch.id) + ')');
  L.push(c.auto + ' ready to apply, ' + c.blocked + ' stopped by the checks, ' + c.manual + ' for a person.');
  for (const x of auto.slice(0, show)) {
    const offices = String(x.after || '').replace(/^business details for Google and AI:?\s*/i, '');
    const what = x.kind === 'noindex' ? '' : (x.kind === 'site_jsonld' ? (offices ? ': ' + esc(cut(offices, 120)) : '')
      : ' → "' + esc(cut(x.after, 160)) + '"');
    L.push('• ' + esc(x.cid) + ' ' + esc(KIND[x.kind] || x.kind) + ', ' + esc(cut(page(x.url), 80)) + what);
  }
  if (auto.length > show) L.push('• and ' + (auto.length - show) + ' more in the file.');
  if (r.batch.manual.length) L.push('For a person: ' + r.batch.manual.length + ' task(s), listed in the file.');
  L.push('');
  L.push('Full report: the file above, or <a href="' + esc(r.run_url) + '">GitHub run ' + esc(r.run_id) + '</a>.');
  L.push('');
  if (row.can_approve) {
    L.push('<b>Yes</b> applies these ' + c.auto + ' change(s) to the live site; each one is skipped if its page changed since the check, '
      + 'and every change can be undone. One yes covers this batch only. Harsh says yes; when he cannot be reached, a teammate, by name.');
    L.push(APPLY_ON ? 'A yes starts "SEO apply fixes" on GitHub at once.'
      : 'For now (test mode) your answer is only recorded: nothing is applied from here yet.');
  } else if (c.auto === 0) {
    L.push('Nothing to approve this week.');
  } else {
    L.push('No Yes button this week: the check missed part of the site. Run "SEO weekly" again on GitHub (Actions) and a new report comes here.');
  }
  return L.join('\n');
}
let show = 15;
let text = build(show);
while (text.length > 4000 && show > 0) text = build(--show);

const file = Buffer.from(String(r.report_md), 'utf8').toString('base64');
const out = [];
for (const chat of plan.admins) {
  out.push({ json: { kind: 'file', chat_id: chat, caption: 'DTJ search report ' + day + ' (batch ' + r.batch.id + ', run ' + r.run_id + ')' },
    binary: { data: { data: file, mimeType: 'text/markdown', fileName: 'dtj-seo-report-' + day + '.md', fileExtension: 'md' } } });
  out.push({ json: { kind, chat_id: chat, text: cut(text, 4096), yes_data: 'seo:yes:' + rowId, no_data: 'seo:no:' + rowId,
    yes_text: 'Yes, apply these ' + c.auto, no_text: 'No, not this batch' } });
}
return out;

// n8n Code node "Dead Letter Alert" in "SEO Engine: Weekly Report" (mode: Run Once for All Items).
// After "Keep in Dead Letter" saved a report that failed its signature or schema check (CLAUDE.md rule 8: nothing else runs for
// it): tell the admins once, in plain words, with the reason and where it is kept. No Yes button, no batch.
// Output: items { chat_id, text } for "Send".
const plan = $('Plan the Report').first().json;
const kept = $input.first().json || {};
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const text = 'The Monday SEO report reached n8n but did not pass its checks, so it was not shown and nothing can be approved from it.\n\n'
  + 'Why: ' + esc(plan.dead.reason) + '\n'
  + 'Kept in the data table dtj_dead_letter' + (kept.id ? ' (row ' + esc(kept.id) + ')' : '') + '. '
  + 'The report itself is safe in the GitHub run (Actions > SEO weekly). Ask Claude Code to look at it.';
return (plan.admins || []).map((chat) => ({ json: { chat_id: chat, text } }));

// n8n Code node "Decide the Answer" in "SEO Engine: Weekly Report" (mode: Run Once for All Items).
// A tap on the report's Yes / No (or on the teammate's "Harsh can't be reached" confirm), handed over by the bot's "Who Is It" as
// { row_id, answer: yes | no | yesnr | cancel, by, user_id, chat_id }.
// The rule (CLAUDE.md rule 2): applying the batch is Tier 2. One named yes covers ONE batch: Harsh's, or, when Harsh is not
// reachable, a DTJ teammate's (an active person in dtj_bot_users), recorded as "<name> (Harsh not reachable)". So a teammate's Yes
// first asks them to confirm that Harsh can't be reached. Harsh = the active bot user whose name has the word "Harsh".
// A batch takes one answer: once it is answered, replaced by a newer report or 7 days old, its buttons only explain why not.
// APPLY_ON false (shadow, Harsh's rule "shadow first"): a yes is recorded with its name and nothing is started; Harsh's yes turns it
// on (n8n/seo-engine/README.md). Then a yes starts GitHub's "SEO apply fixes" with this batch's run, the name and the batch id.
// Output: one item, action "record" (to "Save the Answer"), "confirm" (to "Ask Who Approves") or "reply" (to "Send").
const APPLY_ON = false;
const MAX_AGE_DAYS = 7;
const tap = $('Answer from the Bot').first().json || {};  // (this node's own input is the team rows)
const users = $('Load the Team').all().map((i) => i.json).filter((u) => u && u.telegram_user_id && u.active !== false);
const rows = $('Find the Batch').all().map((i) => i.json).filter((b) => b && b.batch_id);
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const chat = String(tap.chat_id || '');
const reply = (text) => [{ json: { action: 'reply', chat_id: chat, text } }];
const me = users.find((u) => String(u.telegram_user_id).trim() === String(tap.user_id || '').trim());
if (!me) return reply('Only the DTJ team can answer the SEO fixes batch.');
const name = String(me.name || tap.by || '').trim();
if (!name) return reply('Your name is missing in the team list (dtj_bot_users), so your answer cannot be recorded. Ask an admin to add it.');
const answer = String(tap.answer || '');
if (!['yes', 'no', 'yesnr', 'cancel'].includes(answer)) return reply('That button is not valid any more.');
const row = rows.find((b) => Number(b.id) === Number(tap.row_id));
if (!row) return reply('I cannot find that fixes batch any more.');
const label = 'batch ' + esc(row.batch_id) + ' (GitHub run ' + esc(row.run_id) + ')';
if (answer === 'cancel') return reply('OK, nothing recorded. The buttons under the report still work.');
if (row.status !== 'waiting') {
  if (row.status === 'yes' || row.status === 'no') {
    return reply('This ' + label + ' was already answered: ' + esc(row.status) + ' by ' + esc(row.answered_by) + ' on '
      + esc(String(row.answered_at).slice(0, 16).replace('T', ' ')) + ' UTC. One answer per batch.');
  }
  return reply('There is nothing to approve in this ' + label + '.');
}
const newest = Math.max(...rows.map((b) => Number(b.id) || 0));
if (Number(row.id) < newest) {
  return reply('This ' + label + ' was replaced by a newer report. Answer the newest one instead; nothing was recorded.');
}
const made = Date.parse(row.made_at || row.received_at || '');
if (!Number.isFinite(made) || Date.now() - made > MAX_AGE_DAYS * 86400000) {
  return reply('This ' + label + ' is more than ' + MAX_AGE_DAYS + ' days old, so the site may have changed. Next Monday\'s report brings a fresh batch.');
}
if (answer !== 'no' && row.can_approve !== true) return reply('There is nothing to approve in this ' + label + '.');

const isHarsh = /\bharsh\b/i.test(name);
if (answer === 'yes' && !isHarsh) {
  return [{ json: { action: 'confirm', chat_id: chat,
    text: 'Applying this ' + label + ' needs Harsh\'s yes. A teammate may say yes only when Harsh cannot be reached.\n\n'
      + 'Is that the case now? Your yes is then recorded as "' + esc(name) + ' (Harsh not reachable)".',
    yes_data: 'seo:yesnr:' + row.id, no_data: 'seo:cancel:' + row.id,
    yes_text: 'Yes, Harsh can\'t be reached', no_text: 'Cancel' } }];
}
const yes = answer !== 'no';
const approvedBy = !yes ? '' : (isHarsh ? name : name + ' (Harsh not reachable)');
const now = new Date().toISOString();
const others = [...new Set(users.filter((u) => String(u.role || '').toLowerCase().trim() === 'admin')
  .map((u) => String(u.telegram_user_id).trim()).filter((id) => id && id !== chat))];
return [{ json: {
  action: 'record', chat_id: chat, others, row_id: Number(row.id), batch_id: row.batch_id, run_id: String(row.run_id),
  run_url: row.run_url, site: row.site, auto_changes: Number(row.auto_changes) || 0,
  status: yes ? 'yes' : 'no', answered_by: name, approved_by: approvedBy, answered_at: now,
  apply_status: yes ? (APPLY_ON ? 'apply requested (result in dtj_action_log)' : 'shadow: recorded, not applied') : 'not applied (no)',
  dispatch: yes && APPLY_ON,
  body: { ref: 'chore/initial-import', inputs: { run_id: String(row.run_id), approved_by: approvedBy, only: '', batch_id: row.batch_id } },
} }];

// n8n Code node "Answer Messages" in "SEO Engine: Weekly Report" (mode: Run Once for All Items).
// After the answer was saved on its dtj_seo_batches row ("Save the Answer" only passes when the row was still waiting, so two quick
// taps cannot both count) and, when the apply switch is on, after "Start SEO Apply" (GitHub's answer, or its error).
// Tells the person what happened and the other admins who answered. The first item also carries the action-log row ("Log the
// Answer" runs once).
// When "Save the Answer" matched no row, someone else answered a moment earlier: this tap is not counted ("lost").
// "Start SEO Apply" keeps GitHub's answer (full response, never an error): 204 = the run was started.
// Output: items { chat_id, text } for "Send"; the first has log.
const d = $('Decide the Answer').first().json;
const saved = $('Save the Answer').first().json || {};
const got = $input.first().json || {};
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const label = 'batch ' + esc(d.batch_id) + ' (GitHub run ' + esc(d.run_id) + ')';
const applyPage = 'https://github.com/harsh-shopify-dev/dtj-agency-automation/actions/workflows/seo-apply.yml';
const started = Number(got.statusCode) >= 200 && Number(got.statusCode) < 300;
const state = !saved.id ? 'lost' : (d.status === 'no' ? 'no' : (!d.dispatch ? 'shadow' : (started ? 'started' : 'failed')));
const why = got.error ? (got.error.message || got.error.description || JSON.stringify(got.error))
  : ((got.body && got.body.message) || (got.statusCode ? 'GitHub answered ' + got.statusCode : 'no answer from GitHub'));
const err = state === 'failed' ? String(why).slice(0, 300) : (state === 'lost' ? 'someone else answered this batch a moment earlier' : '');
let mine;
let theirs;
if (state === 'lost') {
  mine = 'Someone else answered this ' + label + ' a moment ago, so your tap was not counted. One answer per batch.';
  theirs = null;
} else if (state === 'no') {
  mine = 'Recorded: <b>no</b> to ' + label + ', from ' + esc(d.answered_by) + '. Nothing will be applied from this batch.';
  theirs = esc(d.answered_by) + ' said <b>no</b> to the SEO fixes ' + label + '. Nothing will be applied.';
} else if (state === 'shadow') {
  mine = 'Recorded: <b>yes</b> to ' + label + ', approved by "' + esc(d.approved_by) + '".\n\n'
    + 'Test mode (shadow): nothing was changed on the site. To apply it now, by hand: GitHub > Actions > "SEO apply fixes" > Run workflow, '
    + 'run number ' + esc(d.run_id) + ', approved by "' + esc(d.approved_by) + '", batch ' + esc(d.batch_id) + '.\n' + applyPage;
  theirs = esc(d.approved_by) + ' said <b>yes</b> to the SEO fixes ' + label + '. Test mode: recorded only, nothing applied.';
} else if (state === 'started') {
  mine = 'Yes recorded for ' + label + ', approved by "' + esc(d.approved_by) + '". "SEO apply fixes" has started on GitHub: it applies the '
    + d.auto_changes + ' change(s), checks each live page and keeps the old values for an undo.\n' + applyPage;
  theirs = esc(d.approved_by) + ' said <b>yes</b> to the SEO fixes ' + label + '. "SEO apply fixes" has started.';
} else {
  mine = 'Your yes for ' + label + ' is recorded, but GitHub did not start "SEO apply fixes": ' + esc(err) + '\n'
    + 'Nothing was changed on the site. Start it by hand: run number ' + esc(d.run_id) + ', approved by "' + esc(d.approved_by) + '", batch '
    + esc(d.batch_id) + '.\n' + applyPage;
  theirs = esc(d.approved_by) + ' said <b>yes</b> to the SEO fixes ' + label + ', but GitHub did not start the apply run (see the bot chat).';
}
const log = {
  ts: new Date().toISOString(), run_id: String(d.run_id), client_id: 'dtj', automation: 'seo-engine-n8n', tier: 2,
  mode: d.dispatch ? 'approve' : 'shadow', target: d.site + ' fixes batch ' + d.batch_id,
  action: state === 'started' || state === 'failed' ? 'start SEO apply fixes' : 'record answer on fixes batch',
  reason: 'Monday SEO report: one named yes per batch (CLAUDE.md rule 2)',
  result: { lost: 'blocked', no: 'blocked', shadow: 'recommended', started: 'success', failed: 'failed' }[state],
  evidence: JSON.stringify({ run_url: d.run_url, auto_changes: d.auto_changes, row_id: d.row_id }),
  before: 'waiting', after: state === 'lost' ? 'not changed' : d.status, approved_by: d.approved_by || '', approved_at: d.status === 'yes' ? d.answered_at : '',
  error: err,
};
const out = [{ json: { chat_id: d.chat_id, text: mine, log } }];
if (theirs) for (const chat of d.others || []) out.push({ json: { chat_id: chat, text: theirs } });
return out;
